  'kakao':{ name:'Банановий крем із какао', steps:['Очистьте стиглі банани й наріжте.','Збийте блендером із какао до однорідного крему або дуже ретельно розімніть виделкою.','Розкладіть по мисочках і подавайте одразу.'], photoAlt:'Мисочка темного крему з бананів і какао' },
